import assert from 'node:assert/strict';
import { createController } from './src/controller.js';

const pending = [];
const commits = [];
const records = [];
const renders = [];
const controller = createController({
  service: { commit(snapshot) { commits.push(snapshot); return new Promise((resolve, reject) => pending.push({ resolve, reject })); } },
  audit: { record(entry) { records.push(entry); } },
  render(view) { renders.push(view); },
});

controller.open('a', 'alice');
controller.edit('first');
const first = controller.submit();
controller.edit('second');
const second = controller.submit();
assert.equal(typeof first.then, 'function');
assert.deepEqual(commits, [
  { doc: 'a', actor: 'alice', text: 'first' },
  { doc: 'a', actor: 'alice', text: 'second' },
]);
pending[0].resolve({ revision: 1 });
assert.deepEqual(await first, { revision: 1 });
assert.deepEqual(records, [{ doc: 'a', actor: 'alice', text: 'first', revision: 1 }]);
assert.deepEqual(renders, []);
pending[1].resolve({ revision: 2 });
assert.deepEqual(await second, { revision: 2 });
assert.deepEqual(renders, [{ status: 'saved', doc: 'a' }]);

controller.open('b', 'bob');
controller.edit('kept');
const retained = controller.submit();
controller.close();
controller.open('c', 'cara');
pending[2].resolve({ revision: 3 });
await retained;
assert.deepEqual(records.at(-1), { doc: 'b', actor: 'bob', text: 'kept', revision: 3 });
assert.equal(renders.length, 1);

controller.edit('bad');
const rejected = controller.submit();
pending[3].reject(new Error('nope'));
await assert.rejects(rejected, /nope/);
assert.equal(records.length, 3);
assert.deepEqual(renders.at(-1), { status: 'error', doc: 'c' });
console.log('controller async checks passed');
EOF

